 choices:[{text:'ポート番号',correct:true},{text:'IPアドレス',correct:false}],
 exp1:'TCP/IP通信でアプリケーションを識別する番号。HTTP:80、HTTPS:443、SMTP:25、POP3:110、SSH:22が頻出。',
