 exp1:'Web1.0（静的ページ閲覧）→Web2.0（双方向・SNS・中央集権プラットフォーム）→Web3.0（ブロックチェーンで分散・ユーザーがデータ主権を持つ）という発展。DeFi・NFT・DAOがWeb3.0の代表例。',
